      km:{title:'ដំណោះស្រាយសម្រាប់គ្រប់វិស័យ',lead:'ជ្រើសរើសវិស័យ និងតម្រូវការ ដើម្បីស្វែងយល់ពីរបៀបដែល LEGMAO AI អាចជួយបាន។',industryPrompt:'ជ្រើសរើសវិស័យ',needPrompt:'តើអ្នកចង់ដោះស្រាយបញ្ហាអ្វី?',cta:'ពិភាក្សាអំពីអាជីវកម្ម',industries:['អចលនទ្រព្យ','ហិរញ្ញវត្ថុ','ផលិតកម្ម','លក់រាយ','ភស្តុភារ','សណ្ឋាគារ និងទេសចរណ៍','សុខាភិបាល','អប់រំ','រដ្ឋាភិបាល / សេវាសាធារណៈ'],needs:['បង្កើនអតិថិជន','វិភាគទិន្នន័យ','គ្រប់គ្រងអាជីវកម្ម','ស្វ័យប្រវត្តិកម្ម AI','បម្លែងឌីជីថល','គាំទ្រការសម្រេចចិត្ត'],desc:['ភ្ជាប់ទិន្នន័យអចលនទ្រព្យ ដី និងគម្រោង ដើម្បីគាំទ្រការវិនិយោគ និងការលក់។','ភ្ជាប់សញ្ញាអតិថិជន ហិរញ្ញវត្ថុ និងហានិភ័យ ដើម្បីគាំទ្រសេវាកម្ម និងការសម្រេចចិត្ត។','ប្រមូលទិន្នន័យផលិតកម្ម គុណភាព ខ្សែសង្វាក់ផ្គត់ផ្គង់ និងឧបករណ៍។','ភ្ជាប់អាកប្បកិរិយាអតិថិជន ការលក់ និងស្តុក ដើម្បីកែលម្អហាង។','ជួយសម្របសម្រួល និងបង្កើនប្រសិទ្ធភាពដឹកជញ្ជូន ការបញ្ជាទិញ និងឃ្លាំង។','ប្រើទិន្នន័យភ្ញៀវ ការកក់ និងចំណូល ដើម្បីកែលម្អបទពិសោធន៍។','ភ្ជាប់ទិន្នន័យអ្នកជំងឺ វេជ្ជសាស្ត្រ និងប្រតិបត្តិការ ដើម្បីគាំទ្រសេវាកម្ម។','បម្លែងទិន្នន័យសិស្ស ការចុះឈ្មោះ និងការបង្រៀនទៅជាសកម្មភាពមានប្រយោជន៍។','ភ្ជាប់ទិន្នន័យសាធារណៈ និងប្រតិបត្តិការសេវា ដើម្បីបម្រើសហគមន៍បានឆាប់រហ័ស។'],solutions:[['វិភាគទីផ្សារអចលនទ្រព្យ','វិភាគការវិនិយោគដី និងគម្រោង','គ្រប់គ្រងអចលនទ្រព្យឌីជីថល','គ្រប់គ្រងអតិថិជន និងការលក់','AI ស្វែងរកអតិថិជន','វិភាគដំណើរការគម្រោង'],['វិភាគទិន្នន័យអតិថិជន','កំណត់អត្តសញ្ញាណហានិភ័យ','ទីផ្សារឆ្លាតវៃ','វិភាគទិន្នន័យហិរញ្ញវត្ថុ','សេវាអតិថិជន AI','គាំទ្រការសម្រេចចិត្ត'],['វិភាគទិន្នន័យផលិតកម្ម','គ្រប់គ្រងខ្សែសង្វាក់ផ្គត់ផ្គង់','បង្កើនប្រសិទ្ធភាពស្តុក','វិភាគគុណភាព','តាមដានឧបករណ៍','ថែទាំព្យាករណ៍ដោយ AI'],['ប្រវត្តិរូបអតិថិជន','ទីផ្សារឆ្លាតវៃ','វិភាគការលក់','គ្រប់គ្រងស្តុក','វិភាគប្រតិបត្តិការហាង','ការណែនាំដោយ AI'],['គ្រប់គ្រងការដឹកជញ្ជូន','បង្កើនប្រសិទ្ធភាពផ្លូវ','វិភាគការបញ្ជាទិញ','គ្រប់គ្រងឃ្លាំង','មើលឃើញខ្សែសង្វាក់ផ្គត់ផ្គង់','ព្យាករណ៍ដោយ AI'],['ប្រវត្តិរូបអតិថិជន','វិភាគការកក់','គ្រប់គ្រងចំណូល','គ្រប់គ្រងទំនាក់ទំនងអតិថិជន','ទីផ្សារឆ្លាតវៃ','សេវាកម្ម AI'],['គ្រប់គ្រងទិន្នន័យអ្នកជំងឺ','វិភាគទិន្នន័យវេជ្ជសាស្ត្រ','គ្រប់គ្រងប្រតិបត្តិការ','ជំនួយអតិថិជនឆ្លាតវៃ','វិភាគហានិភ័យ','ជំនួយសម្រេចចិត្តដោយ AI'],['វិភាគទិន្នន័យសិស្ស','គ្រប់គ្រងការចុះឈ្មោះ','វិភាគទិន្នន័យបង្រៀន','ប្រវត្តិរូបសិស្ស','ជំនួយអតិថិជនឆ្លាតវៃ','ជំនួយការបង្រៀន AI'],['វិភាគទិន្នន័យសាធារណៈ','វិភាគប្រតិបត្តិការទីក្រុង','គ្រប់គ្រងសេវាកម្ម','បង្ហាញទិន្នន័យជារូបភាព','ព្រមានហានិភ័យ','គាំទ្រការសម្រេចចិត្តដោយ AI']]}
