    const businessI18n=Object.fromEntries(Object.entries(businessCopy).map(([lang,copy])=>[lang,Object.fromEntries(businessKeys.map((key,i)=>[key,copy.split('|')[i]]))]));
    const workflowKeys='demoStoryTitle|demoStoryLead|workflowTitle|workflowLead|workStep1|workStep2|workStep3|workStep4|workStep5|workStep6|scenarioTitle|scenarioLead|scenarioSalesCopy|scenarioOpsCopy|scenarioManageCopy|scenarioDecisionCopy|industryBridge'.split('|');
    const workflowCopy={
      en:'Let AI take part<br><span>in real work.</span>|From gathering information and analyzing data to creating a plan and moving execution forward, AI can take part in a complete business workflow.|From one AI task to<br><span>a complete business workflow.</span>|AI can connect multiple work steps across a business, not just complete one task.|Gather information|AI analysis|Find issues / opportunities|Create a plan|Execute tasks|Feed back results|How does AI take part<br><span>in real business work?</span>|From sales to operations, management and decisions, AI can take part in more of the work that matters.|Identify customer opportunities → Recommend follow-up → Create tasks automatically|Analyze business data → Find anomalies → Move resolution forward|Summarize operating data → Create reports → Alert owners|Analyze market and company data → Compare options → Support decisions|Different industries need different ways of working with AI.',
      zh:'让 AI 真正参与<br><span>企业工作</span>|从获取信息、分析数据，到生成方案和推动执行，AI 可以参与完整的业务流程。|从一项 AI 任务到<br><span>完整的业务流程</span>|AI 不只完成单项任务，还能连接企业中的多个工作环节。|获取信息|AI 分析|发现问题 / 机会|生成方案|执行任务|反馈结果|AI 如何参与<br><span>企业实际工作？</span>|从销售、运营到管理与决策，让 AI 参与更多真正重要的工作。|AI 识别客户机会 → 推荐跟进策略 → 自动生成任务|AI 分析业务数据 → 发现异常 → 推动处理|AI 汇总经营数据 → 生成报告 → 提醒负责人|AI 分析市场与企业数据 → 比较方案 → 辅助决策|不同行业，需要不同的 AI 工作方式。',
      'zh-tw':'讓 AI 真正參與<br><span>企業工作</span>|從取得資訊、分析數據，到產生方案並推動執行，AI 可以參與完整的業務流程。|從一項 AI 任務到<br><span>完整的業務流程</span>|AI 不只完成單一任務，也能連結企業中的多個工作環節。|取得資訊|AI 分析|發現問題 / 機會|產生方案|執行任務|回饋結果|AI 如何參與<br><span>企業實際工作？</span>|從銷售、營運到管理與決策，讓 AI 參與更多真正重要的工作。|AI 辨識客戶機會 → 建議跟進策略 → 自動建立任務|AI 分析業務數據 → 發現異常 → 推動處理|AI 彙整營運數據 → 產生報告 → 提醒負責人|AI 分析市場與企業數據 → 比較方案 → 輔助決策|不同產業，需要不同的 AI 工作方式。',
      ja:'AIを実務に取り入れる<br><span>仕事に参加するAI</span>|情報収集とデータ分析から、計画の作成、実行の推進まで、AIは業務プロセス全体に参加できます。|一つのAIタスクから<br><span>業務プロセス全体へ</span>|AIは一つの作業をこなすだけでなく、企業内の複数の業務工程をつなぎます。|情報を取得|AIが分析|課題・機会を発見|計画を作成|タスクを実行|結果をフィードバック|AIは企業の実務に<br><span>どう参加するのか？</span>|営業から運用、管理、意思決定まで、重要な業務にAIを活用できます。|顧客機会を特定 → フォロー方法を提案 → タスクを自動作成|業務データを分析 → 異常を発見 → 対応を推進|経営データを集約 → レポート作成 → 担当者に通知|市場と社内データを分析 → 選択肢を比較 → 意思決定を支援|業界によって、AIの活用方法は異なります。',
      ko:'AI가 실제 업무에<br><span>참여하도록 하세요</span>|정보 수집과 데이터 분석부터 계획 수립과 실행 추진까지 AI는 전체 업무 흐름에 참여할 수 있습니다.|하나의 AI 작업에서<br><span>완전한 업무 흐름으로</span>|AI는 단일 작업을 넘어 기업의 여러 업무 단계를 연결할 수 있습니다.|정보 수집|AI 분석|문제 / 기회 발견|계획 생성|작업 실행|결과 피드백|AI는 실제 업무에<br><span>어떻게 참여할까요?</span>|영업부터 운영, 관리와 의사결정까지 중요한 업무에 AI를 참여시킵니다.|고객 기회 파악 → 후속 전략 추천 → 작업 자동 생성|업무 데이터 분석 → 이상 발견 → 해결 추진|운영 데이터 요약 → 보고서 생성 → 담당자 알림|시장 및 기업 데이터 분석 → 대안 비교 → 의사결정 지원|업종마다 AI 업무 방식은 달라야 합니다.',
      th:'ให้ AI มีส่วนร่วม<br><span>ในงานจริง</span>|ตั้งแต่รวบรวมข้อมูลและวิเคราะห์ ไปจนถึงสร้างแผนและผลักดันการดำเนินงาน AI มีส่วนร่วมได้ตลอดกระบวนการธุรกิจ|จากงาน AI หนึ่งงานสู่<br><span>กระบวนการธุรกิจครบวงจร</span>|AI เชื่อมโยงหลายขั้นตอนการทำงานในองค์กร ไม่ได้ทำเพียงงานเดียว|รวบรวมข้อมูล|AI วิเคราะห์|ค้นหาปัญหา / โอกาส|สร้างแผน|ดำเนินงาน|ส่งผลตอบกลับ|AI มีส่วนร่วมในงานจริง<br><span>ขององค์กรอย่างไร?</span>|ตั้งแต่การขาย ปฏิบัติการ การบริหาร ไปจนถึงการตัดสินใจ ให้ AI มีส่วนร่วมในงานสำคัญ|ระบุโอกาสลูกค้า → แนะนำการติดตาม → สร้างงานอัตโนมัติ|วิเคราะห์ข้อมูลธุรกิจ → พบความผิดปกติ → ผลักดันการแก้ไข|สรุปข้อมูลดำเนินงาน → สร้างรายงาน → แจ้งผู้รับผิดชอบ|วิเคราะห์ข้อมูลตลาดและองค์กร → เปรียบเทียบทางเลือก → สนับสนุนการตัดสินใจ|แต่ละอุตสาหกรรมต้องการวิธีทำงานร่วมกับ AI ที่แตกต่างกัน',
      vi:'Để AI tham gia<br><span>vào công việc thực tế</span>|Từ thu thập thông tin, phân tích dữ liệu đến lập phương án và thúc đẩy thực thi, AI có thể tham gia toàn bộ quy trình.|Từ một nhiệm vụ AI đến<br><span>quy trình kinh doanh hoàn chỉnh</span>|AI có thể kết nối nhiều khâu công việc trong doanh nghiệp, không chỉ hoàn thành một nhiệm vụ.|Thu thập thông tin|AI phân tích|Tìm vấn đề / cơ hội|Tạo phương án|Thực hiện nhiệm vụ|Phản hồi kết quả|AI tham gia công việc<br><span>thực tế như thế nào?</span>|Từ bán hàng, vận hành đến quản lý và quyết định, AI tham gia thêm nhiều công việc quan trọng.|Nhận diện cơ hội khách hàng → Đề xuất cách theo dõi → Tự tạo nhiệm vụ|Phân tích dữ liệu kinh doanh → Tìm bất thường → Thúc đẩy xử lý|Tổng hợp dữ liệu vận hành → Tạo báo cáo → Nhắc người phụ trách|Phân tích dữ liệu thị trường và doanh nghiệp → So sánh phương án → Hỗ trợ quyết định|Mỗi ngành cần một cách làm việc với AI khác nhau.',
      id:'Libatkan AI<br><span>dalam pekerjaan nyata</span>|Dari mengumpulkan informasi dan menganalisis data hingga membuat rencana dan mendorong pelaksanaan, AI dapat terlibat dalam seluruh alur bisnis.|Dari satu tugas AI menuju<br><span>alur kerja bisnis lengkap</span>|AI dapat menghubungkan berbagai tahap kerja di perusahaan, bukan hanya menyelesaikan satu tugas.|Kumpulkan informasi|Analisis AI|Temukan masalah / peluang|Buat rencana|Jalankan tugas|Umpan balik hasil|Bagaimana AI terlibat<br><span>dalam pekerjaan nyata?</span>|Dari penjualan dan operasi hingga manajemen dan keputusan, AI dapat membantu lebih banyak pekerjaan penting.|Kenali peluang pelanggan → Sarankan tindak lanjut → Buat tugas otomatis|Analisis data bisnis → Temukan anomali → Dorong penyelesaian|Rangkum data operasional → Buat laporan → Ingatkan penanggung jawab|Analisis data pasar dan perusahaan → Bandingkan opsi → Dukung keputusan|Setiap industri memerlukan cara kerja AI yang berbeda.',
      km:'ឱ្យ AI ចូលរួម<br><span>ក្នុងការងារពិត</span>|ចាប់ពីប្រមូលព័ត៌មាន និងវិភាគទិន្នន័យ រហូតដល់បង្កើតផែនការ និងជំរុញការអនុវត្ត AI អាចចូលរួមក្នុងដំណើរការអាជីវកម្មទាំងមូល។|ពីភារកិច្ច AI មួយទៅកាន់<br><span>ដំណើរការអាជីវកម្មពេញលេញ</span>|AI អាចភ្ជាប់ជំហានការងារជាច្រើនក្នុងសហគ្រាស មិនមែនត្រឹមបំពេញភារកិច្ចមួយទេ។|ទទួលព័ត៌មាន|AI វិភាគ|រកបញ្ហា / ឱកាស|បង្កើតផែនការ|អនុវត្តភារកិច្ច|ផ្តល់មតិត្រឡប់|តើ AI ចូលរួមក្នុង<br><span>ការងារពិតយ៉ាងដូចម្តេច?</span>|ពីការលក់ ប្រតិបត្តិការ និងការគ្រប់គ្រង ដល់ការសម្រេចចិត្ត ឱ្យ AI ចូលរួមការងារសំខាន់ៗ។|សម្គាល់ឱកាសអតិថិជន → ណែនាំការតាមដាន → បង្កើតភារកិច្ចស្វ័យប្រវត្តិ|វិភាគទិន្នន័យអាជីវកម្ម → រកភាពមិនប្រក្រតី → ជំរុញការដោះស្រាយ|សង្ខេបទិន្នន័យប្រតិបត្តិការ → បង្កើតរបាយការណ៍ → ជូនដំណឹងអ្នកទទួលខុសត្រូវ|វិភាគទិន្នន័យទីផ្សារ និងសហគ្រាស → ប្រៀបធៀបជម្រើស → គាំទ្រការសម្រេចចិត្ត|វិស័យនីមួយៗត្រូវការរបៀបធ្វើការជាមួយ AI ផ្សេងៗគ្នា។',
      fr:'De la tâche IA au<br><span>processus métier complet</span>|L’IA peut relier plusieurs étapes du travail en entreprise, au-delà d’une tâche isolée.|D’une tâche IA à<br><span>un processus métier complet</span>|L’IA relie plusieurs étapes du travail dans l’entreprise au lieu de réaliser une seule tâche.|Collecter les informations|Analyse IA|Détecter problèmes / opportunités|Créer un plan|Exécuter les tâches|Retour sur les résultats|Comment l’IA participe-t-elle<br><span>au travail réel ?</span>|De la vente aux opérations, à la gestion et aux décisions, l’IA peut contribuer aux tâches importantes.|Repérer les opportunités client → Recommander le suivi → Créer les tâches automatiquement|Analyser les données métier → Détecter les anomalies → Faire avancer leur traitement|Résumer les données opérationnelles → Créer des rapports → Alerter les responsables|Analyser le marché et l’entreprise → Comparer les options → Éclairer les décisions|Chaque secteur a besoin d’une façon différente de travailler avec l’IA.',
      es:'De una tarea de IA a<br><span>un proceso empresarial completo</span>|La IA puede conectar varias etapas del trabajo en una empresa, no solo completar una tarea.|De una tarea de IA a<br><span>un proceso empresarial completo</span>|La IA conecta varias etapas del trabajo empresarial en lugar de realizar una sola tarea.|Recopilar información|Análisis de IA|Detectar problemas / oportunidades|Crear un plan|Ejecutar tareas|Devolver resultados|¿Cómo participa la IA<br><span>en el trabajo real?</span>|Desde ventas y operaciones hasta gestión y decisiones, la IA puede participar en más tareas importantes.|Identificar oportunidades de clientes → Recomendar seguimiento → Crear tareas automáticamente|Analizar datos del negocio → Detectar anomalías → Impulsar su resolución|Resumir datos operativos → Crear informes → Avisar a responsables|Analizar datos del mercado y la empresa → Comparar opciones → Apoyar decisiones|Cada sector necesita una forma distinta de trabajar con IA.',
      de:'Von einer KI-Aufgabe zum<br><span>vollständigen Geschäftsprozess</span>|KI kann mehrere Arbeitsschritte im Unternehmen verbinden, statt nur eine einzelne Aufgabe zu erledigen.|Von einer KI-Aufgabe zum<br><span>vollständigen Geschäftsprozess</span>|KI verbindet mehrere Arbeitsschritte im Unternehmen und erledigt nicht nur eine Einzelaufgabe.|Informationen erfassen|KI-Analyse|Probleme / Chancen erkennen|Plan erstellen|Aufgaben ausführen|Ergebnisse zurückmelden|Wie wirkt KI bei der<br><span>praktischen Arbeit mit?</span>|Von Vertrieb und Betrieb bis Management und Entscheidungen: KI kann wichtige Aufgaben unterstützen.|Kundenchancen erkennen → Nachfassstrategie empfehlen → Aufgaben automatisch erstellen|Geschäftsdaten analysieren → Abweichungen finden → Bearbeitung voranbringen|Betriebsdaten zusammenfassen → Berichte erstellen → Verantwortliche informieren|Markt- und Unternehmensdaten analysieren → Optionen vergleichen → Entscheidungen unterstützen|Jede Branche braucht eine passende Art der Zusammenarbeit mit KI.'
    };
    Object.entries(workflowCopy).forEach(([lang,copy])=>Object.assign(businessI18n[lang],Object.fromEntries(workflowKeys.map((key,i)=>[key,copy.split('|')[i]]))));
    const industryOutcomeI18n={
      en:{solutions:'AI solutions',outcome:'Business outcome',intro:'AI does more than complete tasks. It helps change how work moves forward.',choose:'Choose a need to see the business outcome for this industry.',results:['Reduce manual screening and repeated follow-up so sales can focus on high-value prospects in {industry}.','Surface market, asset and operating opportunities and risks in {industry} sooner.','Keep projects, customers and tasks visible together to reduce management blind spots in {industry}.','Automate repeat processes in {industry} to shorten handling time.','Move key workflows in {industry} from manual work toward intelligent coordination.','Give decision-makers in {industry} timely insights and actionable recommendations.']},
      zh:{solutions:'AI 解决方案',outcome:'业务结果',intro:'AI 不只是帮助完成任务，更能推动业务工作方式向前。',choose:'选择一项需求，查看该行业对应的业务结果。',results:['减少{industry}中的人工筛选与重复跟进，让销售时间集中在高价值客户上。','更快发现{industry}市场、资产和经营中的机会与风险。','让{industry}的项目、客户与任务信息集中可见，减少管理盲区。','把{industry}的重复流程交给 AI 执行，缩短处理时间。','让{industry}的关键流程逐步从人工操作转向智能协同。','让{industry}管理层更快获得关键信息和可执行建议。']},
      'zh-tw':{solutions:'AI 解決方案',outcome:'業務成果',intro:'AI 不只協助完成任務，也能推動業務工作方式向前。',choose:'選擇一項需求，查看該產業對應的業務成果。',results:['減少{industry}中的人工篩選與重複跟進，讓銷售專注高價值客戶。','更快發現{industry}市場、資產與營運中的機會和風險。','集中呈現{industry}的專案、客戶與任務資訊，減少管理盲點。','將{industry}的重複流程交由 AI 執行，縮短處理時間。','讓{industry}的關鍵流程逐步從人工操作轉為智慧協作。','讓{industry}管理層更快取得關鍵資訊與可執行建議。']},
      ja:{solutions:'AIソリューション',outcome:'業務上の成果',intro:'AIは作業を完了するだけでなく、仕事の進め方を前進させます。',choose:'課題を選ぶと、この業界で期待できる成果を確認できます。',results:['手作業での選別や繰り返しの連絡を減らし、{industry}の営業が有望顧客に集中できます。','{industry}の市場、資産、運営に潜む機会とリスクをより早く把握します。','案件、顧客、タスクをまとめて可視化し、{industry}の管理漏れを減らします。','{industry}の反復業務を自動化し、処理時間を短縮します。','{industry}の重要な業務を手作業から段階的にスマートな連携へ移行します。','{industry}の意思決定者に重要情報と実行可能な提案を迅速に届けます。']},
      ko:{solutions:'AI 솔루션',outcome:'비즈니스 성과',intro:'AI는 작업을 끝내는 데 그치지 않고 업무 방식의 발전을 돕습니다.',choose:'과제를 선택하면 해당 산업에서 기대할 수 있는 성과를 확인할 수 있습니다.',results:['수동 선별과 반복 후속 연락을 줄여 {industry} 영업팀이 가치 높은 고객에 집중합니다.','{industry}의 시장, 자산, 운영에서 기회와 위험을 더 빠르게 파악합니다.','프로젝트, 고객, 작업을 한눈에 관리해 {industry}의 관리 사각지대를 줄입니다.','{industry}의 반복 프로세스를 자동화해 처리 시간을 단축합니다.','{industry}의 핵심 업무를 수작업에서 지능형 협업으로 단계적으로 전환합니다.','{industry} 의사결정자에게 핵심 정보와 실행 가능한 제안을 더 빠르게 제공합니다.']},
      th:{solutions:'โซลูชัน AI',outcome:'ผลลัพธ์ทางธุรกิจ',intro:'AI ไม่ได้เพียงทำงานให้เสร็จ แต่ช่วยให้วิธีทำงานของธุรกิจเดินหน้า',choose:'เลือกความต้องการเพื่อดูผลลัพธ์ทางธุรกิจสำหรับอุตสาหกรรมนี้',results:['ลดการคัดกรองด้วยมือและการติดตามซ้ำ เพื่อให้ทีมขายใน{industry}มุ่งเน้นลูกค้าที่มีคุณค่าสูง','ค้นพบโอกาสและความเสี่ยงด้านตลาด สินทรัพย์ และการดำเนินงานใน{industry}ได้เร็วขึ้น','มองเห็นโครงการ ลูกค้า และงานร่วมกัน ลดจุดบอดในการจัดการของ{industry}','ให้ AI จัดการขั้นตอนซ้ำใน{industry} เพื่อลดเวลาในการดำเนินการ','เปลี่ยนกระบวนการสำคัญใน{industry}จากงานมือไปสู่การทำงานร่วมกันอย่างชาญฉลาด','ช่วยให้ผู้บริหารใน{industry}ได้รับข้อมูลสำคัญและคำแนะนำที่นำไปใช้ได้เร็วขึ้น']},
      vi:{solutions:'Giải pháp AI',outcome:'Kết quả kinh doanh',intro:'AI không chỉ hoàn thành nhiệm vụ mà còn giúp cách thức làm việc tiến lên.',choose:'Chọn nhu cầu để xem kết quả kinh doanh phù hợp với ngành này.',results:['Giảm sàng lọc thủ công và theo dõi lặp lại để đội ngũ bán hàng {industry} tập trung vào khách hàng giá trị cao.','Phát hiện sớm hơn cơ hội và rủi ro về thị trường, tài sản và vận hành trong {industry}.','Hiển thị tập trung dự án, khách hàng và nhiệm vụ để giảm điểm mù quản lý trong {industry}.','Tự động hóa quy trình lặp lại trong {industry} để rút ngắn thời gian xử lý.','Từng bước chuyển quy trình trọng yếu trong {industry} từ thao tác thủ công sang phối hợp thông minh.','Giúp lãnh đạo {industry} nhanh chóng có thông tin quan trọng và đề xuất khả thi.']},
      id:{solutions:'Solusi AI',outcome:'Hasil bisnis',intro:'AI bukan hanya menyelesaikan tugas, tetapi membantu cara kerja bisnis terus maju.',choose:'Pilih kebutuhan untuk melihat hasil bisnis bagi industri ini.',results:['Kurangi penyaringan manual dan tindak lanjut berulang agar tim penjualan {industry} fokus pada prospek bernilai tinggi.','Temukan peluang dan risiko pasar, aset, serta operasional {industry} lebih cepat.','Satukan visibilitas proyek, pelanggan, dan tugas untuk mengurangi titik buta pengelolaan {industry}.','Otomatiskan proses berulang di {industry} untuk mempersingkat waktu penanganan.','Alihkan alur kerja utama {industry} secara bertahap dari pekerjaan manual ke koordinasi cerdas.','Bantu pengambil keputusan {industry} memperoleh wawasan penting dan rekomendasi yang dapat ditindaklanjuti.']},
      km:{solutions:'ដំណោះស្រាយ AI',outcome:'លទ្ធផលអាជីវកម្ម',intro:'AI មិនត្រឹមតែបំពេញភារកិច្ចទេ ប៉ុន្តែជួយឱ្យរបៀបធ្វើការរបស់អាជីវកម្មរីកចម្រើន។',choose:'ជ្រើសរើសតម្រូវការ ដើម្បីមើលលទ្ធផលអាជីវកម្មសម្រាប់វិស័យនេះ។',results:['កាត់បន្ថយការត្រួតពិនិត្យដោយដៃ និងការតាមដានដដែលៗ ដើម្បីឱ្យក្រុមលក់ក្នុង{industry}ផ្តោតលើអតិថិជនមានតម្លៃខ្ពស់។','រកឃើញឱកាស និងហានិភ័យទីផ្សារ ទ្រព្យសកម្ម និងប្រតិបត្តិការ ក្នុង{industry}បានលឿនជាងមុន។','មើលឃើញគម្រោង អតិថិជន និងភារកិច្ចរួមគ្នា កាត់បន្ថយចំណុចខ្វះខាតក្នុងការគ្រប់គ្រង{industry}។','ឱ្យ AI ដំណើរការជំហានដដែលៗក្នុង{industry} ដើម្បីកាត់បន្ថយពេលវេលា។','ផ្លាស់ប្តូរលំហូរការងារសំខាន់ៗក្នុង{industry}ពីការធ្វើដោយដៃទៅការសហការឆ្លាតវៃជាបន្តបន្ទាប់។','ជួយអ្នកសម្រេចចិត្តក្នុង{industry}ទទួលបានព័ត៌មានសំខាន់ និងអនុសាសន៍ដែលអាចអនុវត្តបានលឿន។']},
      fr:{solutions:'Solutions IA',outcome:'Résultat métier',intro:'L’IA ne se contente pas d’exécuter une tâche : elle fait avancer la façon de travailler.',choose:'Choisissez un besoin pour voir le résultat métier associé à ce secteur.',results:['Réduisez le tri manuel et les relances répétées pour que les ventes en {industry} se concentrent sur les prospects à forte valeur.','Repérez plus tôt les opportunités et les risques de marché, d’actifs et d’exploitation en {industry}.','Rendez projets, clients et tâches visibles ensemble pour réduire les angles morts de gestion en {industry}.','Automatisez les processus répétitifs en {industry} pour raccourcir les délais de traitement.','Faites évoluer progressivement les processus clés en {industry} du manuel vers une coordination intelligente.','Donnez aux décideurs en {industry} des informations clés et des recommandations exploitables plus rapidement.']},
      es:{solutions:'Soluciones de IA',outcome:'Resultado empresarial',intro:'La IA no solo completa tareas; también impulsa una nueva forma de trabajar.',choose:'Elige una necesidad para ver el resultado empresarial de este sector.',results:['Reduce la selección manual y los seguimientos repetidos para que ventas en {industry} se centre en clientes de alto valor.','Detecta antes oportunidades y riesgos de mercado, activos y operaciones en {industry}.','Reúne proyectos, clientes y tareas en una vista para reducir puntos ciegos de gestión en {industry}.','Automatiza procesos repetitivos en {industry} para acortar los tiempos de gestión.','Transforma gradualmente los procesos clave de {industry}, del trabajo manual a la coordinación inteligente.','Ofrece a quienes deciden en {industry} información clave y recomendaciones prácticas con mayor rapidez.']},
      de:{solutions:'KI-Lösungen',outcome:'Geschäftsergebnis',intro:'KI erledigt nicht nur Aufgaben, sondern bringt die Arbeitsweise im Unternehmen voran.',choose:'Wählen Sie einen Bedarf, um das passende Geschäftsergebnis für diese Branche zu sehen.',results:['Weniger manuelle Vorauswahl und wiederholte Nachfassaktionen, damit sich der Vertrieb in {industry} auf wertvolle Kontakte konzentriert.','Chancen und Risiken in Markt, Vermögenswerten und Betrieb in {industry} früher erkennen.','Projekte, Kunden und Aufgaben gemeinsam sichtbar machen und Managementlücken in {industry} verringern.','Wiederkehrende Abläufe in {industry} automatisieren und Bearbeitungszeiten verkürzen.','Zentrale Prozesse in {industry} schrittweise von manueller Arbeit zu intelligenter Zusammenarbeit führen.','Entscheidern in {industry} schneller wichtige Informationen und umsetzbare Empfehlungen bereitstellen.']}
    };
    function renderIndustry(activeLang){const d=industryI18n[activeLang]||industryI18n.en;const copy=businessI18n[activeLang]||{};const outcome=industryOutcomeI18n[activeLang]||industryOutcomeI18n.en;const tabs=document.getElementById('industryTabs'),needs=document.getElementById('industryNeeds'),solutions=document.getElementById('industrySolutions');if(!tabs||!needs||!solutions)return;tabs.setAttribute('aria-label',d.industryPrompt);needs.setAttribute('aria-label',d.needPrompt);document.querySelector('[data-i18n="industryTitle"]').innerHTML=copy.industryTitle||d.title;document.querySelector('[data-i18n="industryLead"]').textContent=copy.industryLead||d.lead;document.querySelectorAll('[data-industry-ui]').forEach(el=>{const k=el.dataset.industryUi;if(k==='cta')el.firstChild.textContent=d.cta+' ';else el.textContent=k==='industryPrompt'?d.industryPrompt:d.needPrompt});tabs.innerHTML=d.industries.map((name,i)=>`<button aria-controls="industrySolutions" aria-selected="${i===selectedIndustry}" class="industryTab${i===selectedIndustry?' active':''}" id="industryTab${i}" role="tab" tabindex="${i===selectedIndustry?'0':'-1'}" type="button" data-industry="${i}">${name}</button>`).join('');needs.innerHTML=d.needs.map((name,i)=>`<button aria-pressed="${i===selectedNeed}" class="industryNeed${i===selectedNeed?' active':''}" type="button" data-need="${i}">${name}</button>`).join('');const result=selectedNeed<0?outcome.choose:outcome.results[selectedNeed].replaceAll('{industry}',d.industries[selectedIndustry]);solutions.innerHTML=`<div class="industryCurrent"><span class="kicker">${String(selectedIndustry+1).padStart(2,'0')} / 09</span><h3>${d.industries[selectedIndustry]}</h3><p>${d.desc[selectedIndustry]}</p></div><div class="industrySolutionPane"><h4>${outcome.solutions}</h4><div class="industryGrid">${d.solutions[selectedIndustry].map((name,i)=>`<article class="industrySolution${selectedNeed>=0&&solutionMatches(selectedIndustry,selectedNeed).includes(i)?' isHighlighted':''}"><span class="industrySolutionNo">0${i+1}</span><span>${name}</span><span aria-hidden="true" class="industrySolutionArrow">↗</span></article>`).join('')}</div></div><aside aria-live="polite" aria-atomic="true" class="industryOutcome"><span class="kicker">${outcome.outcome}</span><h4>${outcome.intro}</h4><p>${result}</p></aside>`;}
    const needHighlights=[
      [[3,4],[0,1,5],[2,3,5],[4],[2,4,5],[1,5]],
      [[2,4],[0,1,3],[0,5],[2,4],[0,3,4],[1,3,5]],
      [[3,5],[0,2,3,4,5],[1,2,3,4],[4,5],[0,1,2,4],[0,3,5]],
      [[0,1,4,5],[0,2,4],[2,3,4],[1,5],[0,2,3,4],[0,2,4,5]],
      [[2,5],[0,1,2,4,5],[0,2,3,4],[1,4,5],[0,2,3,4],[1,4,5]],
      [[0,1,4,5],[0,1,2,5],[2,3,4],[4,5],[1,2,3,5],[0,2,5]],
      [[3,4],[0,1,4],[0,2,3],[3,5],[0,1,2,3],[1,4,5]],
      [[1,3,4],[0,2,3],[1,2,3],[4,5],[0,2,3,5],[0,2,5]],
      [[2,3],[0,1,3,4],[0,2,3],[3,4,5],[0,2,3,4],[0,1,4,5]]
    ];
    function solutionMatches(industry,need){return need<0?[]:(needHighlights[industry]?.[need]||[])};    function initIndustrySelector(){const tabs=document.getElementById('industryTabs'),needs=document.getElementById('industryNeeds');if(!tabs||!needs)return;tabs.addEventListener('click',e=>{const b=e.target.closest('[data-industry]');if(!b)return;selectedIndustry=Number(b.dataset.industry);renderIndustry(document.documentElement.lang)});tabs.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const i=Number(document.activeElement.dataset.industry);selectedIndustry=e.key==='Home'?0:e.key==='End'?8:(i+(e.key==='ArrowRight'?1:8))%9;renderIndustry(document.documentElement.lang);document.getElementById('industryTab'+selectedIndustry).focus()});needs.addEventListener('click',e=>{const b=e.target.closest('[data-need]');if(!b)return;const n=Number(b.dataset.need);selectedNeed=selectedNeed===n?-1:n;renderIndustry(document.documentElement.lang)});renderIndustry(document.documentElement.lang)}
    initIndustrySelector();    const languageNames={en:'EN · English',zh:'中文 · 简体','zh-tw':'繁體中文',km:'ខ្មែរ · Khmer',ja:'日本語',ko:'한국어',th:'ไทย · Thai',vi:'Tiếng Việt',id:'Bahasa Indonesia',fr:'Français',es:'Español',de:'Deutsch'};
    function applyLanguage(lang){const active=dictionary[lang]?lang:'en',d={...businessI18n.en,...(businessI18n[active]||{}),...dictionary[active]};document.documentElement.lang=active;try{localStorage.setItem('legmao-language',active)}catch(e){}document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(d[key])el.innerHTML=d[key]});document.getElementById('langLabel').textContent=languageNames[active]||languageNames.en;document.querySelectorAll('[data-lang]').forEach(a=>{if(a.dataset.lang===active)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')});return active;}
    function setLanguage(lang,updateUrl=true){const active=applyLanguage(lang);renderIndustry(active);if(updateUrl){const url=new URL(location.href);if(active==='en')url.searchParams.delete('lang');else url.searchParams.set('lang',active);url.hash='top';history.pushState({lang:active},'',url)}return active;}
    let storedLanguage='en';try{storedLanguage=localStorage.getItem('legmao-language')||'en'}catch(e){}const initialLang=applyLanguage(new URLSearchParams(location.search).get('lang')||storedLanguage||'en');
    renderIndustry(initialLang);
    document.querySelectorAll('[data-lang]').forEach(a=>a.addEventListener('click',e=>{
      e.preventDefault();setLanguage(a.dataset.lang);
      const picker=document.getElementById('langPicker');picker.open=false;document.getElementById('langLabel').focus();
    }));
    addEventListener('popstate',()=>{const active=applyLanguage(new URLSearchParams(location.search).get('lang')||'en');renderIndustry(active)});
    document.addEventListener('click',e=>{const picker=document.getElementById('langPicker');if(!picker.contains(e.target))picker.open=false});
    const menuToggle=document.getElementById('menuToggle'),navlinks=document.getElementById('navlinks');
    function setNavOpen(open){navlinks.classList.toggle('open',open);menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');menuToggle.textContent=open?'\u00D7':'\u2630';}
    menuToggle.addEventListener('click',()=>setNavOpen(menuToggle.getAttribute('aria-expanded')!=='true'));
    navlinks.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setNavOpen(false)));
    document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('langPicker').open=false;if(menuToggle.getAttribute('aria-expanded')==='true'){setNavOpen(false);menuToggle.focus()}}});
    addEventListener('resize',()=>{if(innerWidth>650)setNavOpen(false)},{passive:true});
