/* v3 custom cursor — quiet, spatial, brand-like */
(function(){
  if(!matchMedia('(any-pointer:fine)').matches) return;
  const dot=document.getElementById('cursorDot'),ring=document.getElementById('cursorRing');
  if(!dot||!ring)return;
  let x=innerWidth/2,y=innerHeight/2,rx=x,ry=y,ready=false;
  addEventListener('pointermove',e=>{x=e.clientX;y=e.clientY;if(!ready){ready=true;document.body.classList.add('cursor-ready')}} ,{passive:true});
  const interactive='a,button,summary,.capLine,.industryItem,.demoBtn';
  document.addEventListener('pointerover',e=>{if(e.target.closest(interactive))document.body.classList.add('cursor-hover')});
  document.addEventListener('pointerout',e=>{if(e.target.closest(interactive))document.body.classList.remove('cursor-hover')});
  function tick(){rx+=(x-rx)*.85;ry+=(y-ry)*.85;dot.style.left=x+'px';dot.style.top=y+'px';ring.style.left=rx+'px';ring.style.top=ry+'px';requestAnimationFrame(tick)} tick();
})();

/* Premium hero field — sparse particles, soft depth, no spectacle. */
(function(){
  const canvas=document.getElementById('heroParticles');
  const hero=document.querySelector('.hero');
  if(!canvas||!hero)return;
  const motion=matchMedia('(prefers-reduced-motion: reduce)');
  const ctx=canvas.getContext('2d'); let w=0,h=0,dpr=1,raf=0,t=0,px=.5,py=.5,tx=.5,ty=.5;
  const stars=[]; const palette=[[125,143,255],[75,220,255],[202,151,255],[150,170,255]];
  function resize(){
    const r=hero.getBoundingClientRect(); dpr=Math.min(devicePixelRatio||1,2); w=r.width; h=r.height;
    canvas.width=w*dpr; canvas.height=h*dpr; canvas.style.width=w+'px'; canvas.style.height=h+'px'; ctx.setTransform(dpr,0,0,dpr,0,0);
    stars.length=0; const count=Math.min(95,Math.max(38,Math.floor(w/18)));
    for(let i=0;i<count;i++) stars.push({x:Math.random(),y:Math.random(),r:.35+Math.random()*1.15,a:.08+Math.random()*.42,s:.00015+Math.random()*.0005,p:Math.random()*Math.PI*2,c:palette[i%palette.length]});
  }
  function frame(){
    t+=.008; px+=(tx-px)*.035; py+=(ty-py)*.035; ctx.clearRect(0,0,w,h);
    const gx=w*(.76+(px-.5)*.035), gy=h*(.42+(py-.5)*.025), radius=Math.min(w,h)*.48;
    const glow=ctx.createRadialGradient(gx,gy,0,gx,gy,radius);
    glow.addColorStop(0,'rgba(110,126,255,.055)'); glow.addColorStop(.48,'rgba(80,102,230,.018)'); glow.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=glow; ctx.fillRect(0,0,w,h);
    for(const s of stars){
      s.p+=s.s*8; const drift=Math.sin(t+s.p)*7; const x=s.x*w+drift+(px-.5)*18*(1-s.y); const y=s.y*h+Math.cos(t*.7+s.p)*4+(py-.5)*10;
      const pulse=s.a*(.62+.38*Math.sin(t*1.3+s.p)); const c=s.c;
      ctx.fillStyle=`rgba(${c[0]},${c[1]},${c[2]},${pulse})`; ctx.beginPath(); ctx.arc(x,y,s.r,0,Math.PI*2); ctx.fill();
      if(s.r>1.05){ctx.strokeStyle=`rgba(${c[0]},${c[1]},${c[2]},${pulse*.16})`;ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(x-5,y);ctx.lineTo(x+5,y);ctx.moveTo(x,y-5);ctx.lineTo(x,y+5);ctx.stroke();}
    }
    if(!legmaoReduceMotion(motion)&&!document.hidden)raf=requestAnimationFrame(frame);else raf=0;
  }
  function move(e){const r=hero.getBoundingClientRect();tx=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));ty=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));}
  hero.addEventListener('pointermove',move,{passive:true}); hero.addEventListener('pointerleave',()=>{tx=.5;ty=.5},{passive:true});
  function stop(){if(raf){cancelAnimationFrame(raf);raf=0}}function start(){if(document.hidden)return;stop();frame()}function sync(){stop();start()}
  addEventListener('resize',()=>{resize();sync()},{passive:true});document.addEventListener('visibilitychange',sync);motion.addEventListener('change',sync); resize(); start();
})();
